let stocks=[],sort={key:'gap',dir:1},refreshing=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const CORE=['银行','电力/','公用事业/','交运/','通信/运营商','能源/油气开采','周期/煤炭','基建/公用'];
const gap=s=>s.price>0?(s.price-s.target)/s.price*100:null;
const bucket=g=>g==null?'far':g<0?'buy':g<5?'near':g<10?'mid':'far';
const fmt=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toFixed(d);
const codeToQQ=code=>{let [n,m]=code.toUpperCase().split('.');return m==='HK'?'r_hk'+n:m==='SH'?'sh'+n:m==='SZ'?'sz'+n:null};
const persisted=()=>JSON.parse(localStorage.getItem('buyPointRadarCustomV2')||'[]');
function persistCustom(){localStorage.setItem('buyPointRadarCustomV2',JSON.stringify(stocks.filter(s=>s.custom)))}
function filters(){return{q:$('#search').value.trim().toLowerCase(),market:$('#market').value,sat:$('#satellite').value,cat:$('#category').value}}
function visible(){let f=filters();return stocks.filter(s=>(!f.q||(`${s.name}${s.code}${s.category}`).toLowerCase().includes(f.q))&&(f.market==='all'||s.market===f.market)&&(f.sat==='all'||(f.sat==='satellite')===s.satellite)&&(f.cat==='all'||s.category===f.cat)).sort((a,b)=>{let av=sort.key==='gap'?gap(a):a[sort.key],bv=sort.key==='gap'?gap(b):b[sort.key];if(av==null)return 1;if(bv==null)return-1;if(typeof av==='string')return av.localeCompare(bv,'zh-CN')*sort.dir;return(av-bv)*sort.dir})}
function renderStats(){let priced=stocks.filter(s=>s.price>0),gs=priced.map(gap),num=k=>gs.filter(g=>bucket(g)===k).length,up=priced.filter(s=>s.change>0).length,down=priced.filter(s=>s.change<0).length;let cards=[['已到买点',num('buy'),'只','var(--red)'],['接近买点',num('near'),'只','var(--amber)'],['中等距离',num('mid'),'只','var(--blue)'],['等待区',num('far'),'只','var(--green)'],['实时上涨',up,'只','var(--red)'],['实时下跌',down,'只','var(--green)'],['已获取行情',priced.length,'只','var(--ink)']];$('#stats').innerHTML=cards.map(c=>`<article class="stat" style="--tone:${c[3]}"><small>${c[0]}</small><strong>${c[1]}</strong><em>${c[2]}</em></article>`).join('')}
function renderCategories(){let old=$('#category').value;$('#category').innerHTML='<option value="all">全部分类</option>'+[...new Set(stocks.map(s=>s.category))].sort().map(x=>`<option>${x}</option>`).join('');if([...$('#category').options].some(o=>o.value===old))$('#category').value=old}
function render(){let list=visible();$('#resultCount').textContent=`${list.length} / ${stocks.length} 只`;$('#empty').hidden=!!list.length;$('#empty').textContent='没有符合当前条件的标的。';$('#rows').innerHTML=list.map(s=>{let g=gap(s),b=bucket(g),chg=s.change;return `<tr><td class="stock"><b>${s.name}${s.satellite?'<span class="sat">✦</span>':''}</b><small>${s.code} · ${s.market}</small></td><td><span class="tag">${s.category}</span></td><td class="num">${fmt(s.target)}</td><td class="num">${fmt(s.price)}</td><td class="num ${chg>0?'rise':chg<0?'fall':''}">${chg==null?'—':(chg>=0?'+':'')+fmt(chg)+'%'}</td><td class="num"><span class="gap ${b}">${g==null?'待行情':(g>=0?'+':'')+fmt(g)+'%'}</span></td><td class="num">${fmt(s.roe)}${s.roe==null?'':'%'}</td><td class="num">${fmt(s.yield)}${s.yield==null?'':'%'}</td><td><div class="row-menu">${s.custom?`<button data-edit="${s.id}" title="编辑">✎</button><button data-delete="${s.id}" title="删除">×</button>`:''}</div></td></tr>`}).join('');renderStats()}
function loadBatch(batch){return new Promise(resolve=>{let script=document.createElement('script'),done=false,finish=()=>{if(done)return;done=true;let count=0;batch.forEach(s=>{let key=codeToQQ(s.code),raw=key&&window['v_'+key];if(raw){let f=String(raw).split('~'),p=parseFloat(f[3]),prev=parseFloat(f[4]);if(p>0){s.price=p;s.prevClose=prev||null;s.change=prev>0?(p-prev)/prev*100:null;count++}}try{delete window['v_'+key]}catch{}});script.remove();resolve(count)};script.charset='gbk';script.src='https://qt.gtimg.cn/q='+batch.map(s=>codeToQQ(s.code)).filter(Boolean).join(',')+'&_t='+Date.now();script.onload=finish;script.onerror=finish;document.head.appendChild(script);setTimeout(finish,10000)})}
async function refreshPrices(){if(refreshing)return;refreshing=true;$('#refreshBtn').disabled=true;$('#liveStatus').textContent=`正在更新 ${stocks.length} 只股票…`;let total=0;for(let i=0;i<stocks.length;i+=60){total+=await loadBatch(stocks.slice(i,i+60));render()}let t=new Date().toLocaleString('zh-CN',{hour12:false});$('#liveStatus').textContent=`已更新 ${total}/${stocks.length} 只 · ${t} · 每60秒自动刷新`;$('#refreshBtn').disabled=false;refreshing=false}
function openForm(id){$('#stockForm').reset();$('#editId').value='';$('#formTitle').textContent='添加标的';if(id){let s=stocks.find(x=>x.id===id);$('#formTitle').textContent='编辑标的';$('#editId').value=s.id;['Name','Code','Market','Category','Target','Price','Roe','Yield'].forEach(k=>$('#f'+k).value=s[k.toLowerCase()]??'');$('#fSatellite').checked=s.satellite}$('#editor').showModal()}
$('#addBtn').onclick=()=>openForm();$('#refreshBtn').onclick=refreshPrices;
$('#stockForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();let id=Number($('#editId').value)||Date.now(),s={id,name:$('#fName').value.trim(),code:$('#fCode').value.trim().toUpperCase(),market:$('#fMarket').value,category:$('#fCategory').value.trim(),target:Number($('#fTarget').value),price:$('#fPrice').value===''?null:Number($('#fPrice').value),prevClose:null,change:null,roe:$('#fRoe').value===''?null:Number($('#fRoe').value),yield:$('#fYield').value===''?null:Number($('#fYield').value),satellite:$('#fSatellite').checked,custom:true};let i=stocks.findIndex(x=>x.id===id);i<0?stocks.push(s):stocks[i]=s;persistCustom();renderCategories();render();$('#editor').close();refreshPrices()});
$('#rows').onclick=e=>{let id=Number(e.target.dataset.edit||e.target.dataset.delete);if(e.target.dataset.edit)openForm(id);if(e.target.dataset.delete&&confirm('从本地观察清单中删除这个自定义标的？')){stocks=stocks.filter(s=>s.id!==id);persistCustom();renderCategories();render()}};
$$('#search,#market,#satellite,#category').forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',render));
$('#resetBtn').onclick=()=>{$('#search').value='';$('#market').value=$('#satellite').value=$('#category').value='all';render()};
$$('th[data-sort]').forEach(th=>th.onclick=()=>{let key=th.dataset.sort;sort={key,dir:sort.key===key?-sort.dir:1};$$('th').forEach(x=>x.classList.remove('active'));th.classList.add('active');render()});
$('#exportBtn').onclick=()=>{let head=['名称','代码','市场','分类','目标价','现价','日涨跌%','距买点%','ROE%','股息率%','仓位'],body=visible().map(s=>[s.name,s.code,s.market,s.category,s.target,s.price??'',fmt(s.change),fmt(gap(s)),s.roe??'',s.yield??'',s.satellite?'卫星仓':'核心仓']),csv='\uFEFF'+[head,...body].map(r=>r.map(x=>`"${String(x).replaceAll('"','""')}"`).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='买点雷达-'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(a.href)};
(async()=>{try{let data=await fetch('stocks.json',{cache:'no-store'}).then(r=>r.json());stocks=data.map(s=>({...s,satellite:CORE.every(p=>!s.category.startsWith(p))})).concat(persisted())}catch(e){$('#liveStatus').textContent='股票清单载入失败，请刷新页面';return}renderCategories();render();await refreshPrices();setInterval(()=>{if(!document.hidden)refreshPrices()},60000)})();

